INSERT INTO client_releases (version, version_key, platform, file_key, file_name, size, sha256, notes, notes_en, published_at) VALUES ('2.92.0', 2092000, 'windows', 'releases/CosmicPlatformer-Setup-2.92.0.exe', 'CosmicPlatformer-Setup-2.92.0.exe', 160228845, 'a151eebcac2f3ab6ff8fd63c437e85ab230097848609b181d2fb0f8e1c4cfcc6', 'Version 2.92.0 :
• Les animations du niveau démarrent au même moment pour tout le monde : un niveau qui s''ouvre sur son intro attend le chronomètre (ennemis, plateformes, événements, dangers), que l''intro soit regardée ou passée. Simulation 19 ; les replays d''avant se rejouent avec leurs règles, records et classements gardés.
• Titanus allégé, un peu : 15 % de vie en moins, son écrasement, ses ondes de choc et ses rochers espacés d''une seconde, 18 s à genou au lieu de 15 (environ 10 min pour un bon groupe de 8 à 3 / 5).
• Pause : « Mode concentré » et « Invincible (admin) » affichent ACTIVÉ / DÉSACTIVÉ avec le même interrupteur ; la flèche « › » de « Mode concentré » (ou →) ouvre l''éditeur du HUD sur son onglet « Mode concentré » ; Entrée / A refonctionnent sur la pause et les écrans posés par-dessus le jeu.', 'Version 2.92.0:
• Level animations now start at the same moment for everyone: a level that opens on its intro waits for the clock (enemies, platforms, events, hazards), whether the intro is watched or skipped. Simulation 19; older replays play back with their own rules, records and rankings are kept.
• Titanus made a little easier: 15 % less health, its crushing heel, shockwaves and boulders one second further apart, 18 s on its knee instead of 15 (about 10 min for a good group of 8 at 3 / 5).
• Pause: "Focus mode" and "Invincible (admin)" show ON / OFF with the same switch; the "›" arrow on "Focus mode" (or →) opens the HUD editor on its "Focus mode" tab; Enter / A work again on the pause and other screens shown over the game.', '2026-11-27T00:57:45.820Z') ON CONFLICT (version) DO NOTHING;
